insert into public.services (id,slug,name,tagline,description,image,price,active,sort_order) values
('ca5a0000-0000-4000-8000-000000000401','deratizacija','Deratizacija','Procena prostora. Dogovoren tretman.','Deratizacija stanova, kuća, podruma i poslovnih prostora u Beogradu. Procenu problema sa miševima i pacovima, obim tretmana i kontrolu dogovaramo pre dolaska.','/images/services/ddd-zastita.webp',null,true,55),
('ca5a0000-0000-4000-8000-000000000402','dezinsekcija','Dezinsekcija','Procena prostora. Dogovoren tretman.','Dezinsekcija protiv bubašvaba, mrava, buva i drugih insekata u Beogradu. Vrstu štetočine, zahvaćene prostorije, pripremu i obim tretmana potvrđujemo nakon procene.','/images/services/ddd-zastita.webp',null,true,56),
('ca5a0000-0000-4000-8000-000000000403','dezinfekcija','Dezinfekcija prostora','Procena prostora. Dogovoren tretman.','Dezinfekcija dogovorenih površina u stanovima, zgradama i poslovnim prostorima u Beogradu. Namenu prostora, početno stanje, pripremu i cenu potvrđujemo pre tretmana.','/images/services/ddd-zastita.webp',null,true,57),
('ca5a0000-0000-4000-8000-000000000404','tretman-protiv-stenica','Tretman protiv stenica','Procena prostora. Dogovoren tretman.','Procena i tretman protiv stenica u stanovima i smeštajnim objektima u Beogradu. Pregled, pripremu prostorija, plan tretmana i moguće ponovljene posete dogovaramo sa specijalistom.','/images/services/ddd-zastita.webp',null,true,58),
('ca5a0000-0000-4000-8000-000000000405','uklanjanje-gnezda-osa-i-strsljena','Uklanjanje gnezda osa i stršljena','Procena prostora. Dogovoren tretman.','Procena i uklanjanje gnezda osa i stršljena u Beogradu. Položaj gnezda, visinu i pristup proveravamo pre ponude i dogovora o intervenciji odgovarajućeg specijaliste.','/images/services/ddd-zastita.webp',null,true,59),
('ca5a0000-0000-4000-8000-000000000406','preventivna-ddd-zastita','Preventivna DDD zaštita','Procena prostora. Dogovoren tretman.','Preventivni DDD plan za stambene zgrade i poslovne prostore u Beogradu. Preglede, potrebu za tretmanima, učestalost i kontrolne posete dogovaramo prema proceni objekta.','/images/services/ddd-zastita.webp',null,true,60),
('ca5a0000-0000-4000-8000-000000000407','uklanjanje-neprijatnih-mirisa','Uklanjanje neprijatnih mirisa','Procena prostora. Dogovoren tretman.','Procena i uklanjanje neprijatnih mirisa u stanovima i poslovnim prostorima u Beogradu. Izvor mirisa, zahvaćene materijale i odgovarajući postupak proveravamo pre ponude.','/images/services/ddd-zastita.webp',null,true,61),
('ca5a0000-0000-4000-8000-000000000408','ciscenje-posle-ddd-tretmana','Čišćenje posle DDD tretmana','Procena prostora. Dogovoren tretman.','Čišćenje nakon deratizacije, dezinsekcije ili dezinfekcije u Beogradu. Termin, dozvoljene površine i obim čišćenja usklađujemo sa uputstvom izvođača prethodnog tretmana.','/images/services/ddd-zastita.webp',null,true,62),
('ca5a0000-0000-4000-8000-000000000409','sanacija-budji','Sanacija buđi','Procena prostora. Dogovoren tretman.','Procena i sanacija buđi na zidovima i površinama u Beogradu. Stanje podloge, obim zahvaćenih delova i potrebu za rešavanjem vlage proveravamo sa specijalistom pre ponude.','/images/services/ddd-zastita.webp',null,true,63)
